   362|function buildOwnerDeveloperConnectionString(): string {
   363|  const explicitConnectionString = readBackendEnv('SUPABASE_OWNER_DATABASE_URL')
   364|    || readBackendEnv('SUPABASE_DB_URL')
   365|    || readBackendEnv('DATABASE_URL')
   366|    || readBackendEnv('POSTGRES_URL');
   367|  if (explicitConnectionString) {
   368|    return explicitConnectionString;
   369|  }
   370|  const supabaseUrl = readBackendEnv('EXPO_PUBLIC_SUPABASE_URL');
   371|  const password = readBackendEnv('SUPABASE_DB_PASSWORD');
   372|  if (!supabaseUrl || !password) {
   373|    throw new Error('Supabase database connection is not configured server-side.');
   374|  }
   375|  const projectRef = new URL(supabaseUrl).hostname.split('.')[0] ?? '';
   376|  if (!projectRef) {
   377|    throw new Error('Unable to derive Supabase project ref server-side.');
   378|  }
   379|  return `postgres://postgres:${encodeURIComponent(password)}@db.${projectRef}.supabase.co:5432/postgres?sslmode=require&application_name=ivx_owner_developer_tools`;
   380|}
