   382|async function withOwnerDeveloperPg<T>(callback: (client: PgClient) => Promise<T>): Promise<T> {
   383|  const pgModule = await import('pg') as { Pool: PgPoolConstructor };
   384|  const pool = new pgModule.Pool({ connectionString: buildOwnerDeveloperConnectionString(), ssl: { rejectUnauthorized: false }, application_name: 'ivx_owner_developer_tools', max: 1, idleTimeoutMillis: 5_000, connectionTimeoutMillis: 8_000 });
   385|  const client = await pool.connect();
   386|  try {
   387|    return await callback(client);
   388|  } finally {
   389|    client.release();
   390|    await pool.end().catch(() => undefined);
   391|  }
   392|}
