   394|function getBackendServiceRoleKey(): string {
   395|  const anonKey = readBackendEnv('EXPO_PUBLIC_SUPABASE_ANON_KEY');
   396|  const serviceKey = readBackendEnv('SUPABASE_SERVICE_ROLE_KEY') || readBackendEnv('SUPABASE_SERVICE_KEY');
   397|  const role = decodeSupabaseJwtRole(serviceKey);
   398|  if (!serviceKey || serviceKey === anonKey || (role !== 'service_role' && role !== 'supabase_admin')) {
   399|    throw new Error('Backend-only Supabase service-role key is not configured.');
   400|  }
   401|  return serviceKey;
   402|}
