   457|  lines.push(`Task: ${start.task.id} — ${start.task.totalBlocks} block${start.task.totalBlocks === 1 ? '' : 's'}, status ${start.task.status}.`);
   458|  lines.push('Live progress: open the Live Developer Monitor (IVX Owner AI → Developer Monitor) — it streams the current block, file being changed, test result, commit hash, deploy status, production verification, and any blocker.');
